import Foundation

/// The robot's audio-board registers: read one, write a batch.
///
/// A protocol of its own rather than two more methods on ``RobotAPIClient``, for the
/// reason ``SoundboardClient`` is one: conforming *is* the capability. A session over
/// the Hugging Face relay reports it unavailable instead of failing a control somebody
/// just moved.
///
/// The daemon opens a short-lived USB handle for every call and closes it again
/// (`routers/audio_config.py`), so a batch of six registers costs one round trip and
/// six reads cost six. Write a profile, do not write a register at a time.
public protocol AudioTuningClient: Sendable {
    /// Reads one register by name. The daemon answers 404 for a name its map does not
    /// hold, and 503 when no audio board answers on USB.
    func readAudioParameter(named name: String) async throws -> AudioParameter

    /// Writes a batch of registers.
    ///
    /// - Parameter verify: the daemon reads each register back and compares it to
    ///   `1e-3` after the write settles. Leave it on: a refused write is otherwise
    ///   indistinguishable from an accepted one.
    func applyAudioConfig(_ parameters: [AudioParameter], verify: Bool) async throws
}

public extension RobotSession {
    /// False over the relay, whose data channel carries no audio-config commands in
    /// this client. The daemon's own protocol does define them, so this can grow a
    /// remote arm later without the screens above changing.
    var canTuneAudio: Bool {
        client is any AudioTuningClient
    }

    /// Reads back the registers a profile writes, and names the profile they match.
    ///
    /// - Returns: nil for a robot somebody tuned by hand, which is a state to show
    ///   rather than to overwrite.
    func microphoneProfile() async throws -> MicrophoneProfile? {
        let names = MicrophoneProfile.standard.parameters.map(\.name)
        var read: [AudioParameter] = []
        for name in names {
            try await read.append(withAudioTuningClient { try await $0.readAudioParameter(named: name) })
        }
        return MicrophoneProfile.matching(read)
    }

    /// Writes a profile to the audio board.
    ///
    /// - Important: the write is global and it outlives this session — every app on
    ///   the robot hears through the registers this moves. Whether it also outlives a
    ///   reboot is a property of the board, not of this call: the register map holds a
    ///   `SAVE_CONFIGURATION` command that nothing here sends.
    func applyMicrophoneProfile(_ profile: MicrophoneProfile) async throws {
        try await withAudioTuningClient {
            try await $0.applyAudioConfig(profile.parameters, verify: true)
        }
    }
}

extension RobotSession {
    /// Throws and says nothing else, the way ``withSoundboardClient`` does: a control
    /// that failed belongs to the screen that moved it, and `robotError` is the
    /// robot's connection and power alone.
    func withAudioTuningClient<T>(_ call: (any AudioTuningClient) async throws -> T) async throws -> T {
        guard let client else { throw ReachyKitError.notConnected }
        guard let tuning = client as? any AudioTuningClient else {
            throw ReachyKitError.audioTuningUnavailable
        }
        return try await call(tuning)
    }
}

import Foundation
import Observation
import ReachyKit
@preconcurrency import WebRTC

/// Owns one WebRTC session to the robot: consumes `CameraSignalingClient`
/// events, answers the robot's offer, and exposes the remote video track plus
/// a mic toggle (client mic → robot speaker; the robot's offer is sendrecv).
///
/// Self-healing: any failure (ICE, watchdog, socket) drops the peer connection
/// and forces the signaling client to reconnect, which re-negotiates a session.
@MainActor
@Observable
public final class CameraSession {
    public enum Phase: Equatable, Sendable {
        case connecting
        /// Signaling is up but the daemon has no media producer (sim before acquire).
        case waitingForProducer
        case streaming
        case failed(String)
    }

    public private(set) var phase: Phase = .connecting
    public private(set) var videoTrack: RTCVideoTrack?
    public private(set) var isMicEnabled = false

    /// Gain applied to this device's microphone before the robot hears it, where 1 is
    /// unchanged. libwebrtc takes 0…10 and clamps outside that.
    ///
    /// **It exists because the robot has no headroom left.** The daemon applies no
    /// software gain to anything it plays, and its mixer is already at 100, so a call
    /// cannot be made quieter or an app's speech louder from that end. What a person
    /// hears as "the call is much louder than the apps" is the level of the two
    /// sources: this device's voice arrives compressed and near full scale from the
    /// system's voice-processing unit, while a sound asset plays at whatever level it
    /// was recorded — `wake_up.wav` sits 14 dB below `go_sleep.wav`. Lowering this is
    /// the only control over that difference.
    public var micVolume: Double = 1 {
        didSet { micSource?.volume = min(max(micVolume, 0), 10) }
    }

    /// Whether `start()` has run and `stop()` has not — what "the camera is
    /// still up" means to the audio handover when a call ends over it.
    var isRunning: Bool {
        eventsTask != nil
    }

    /// What the OS says about recording. Published because a refusal used to be
    /// swallowed here: `setMicEnabled(true)` returned early and wrote nothing, so the
    /// button redrew itself unchanged and unmuting did nothing, forever, unexplained.
    /// The viewport reads this to say why instead.
    public private(set) var micPermission: PermissionState = .undetermined

    /// The session's control surface. Exists from construction and stays the same
    /// object across re-negotiations, so a `RemoteControlChannel` built on it
    /// survives the self-healing restart that replaces the peer connection.
    ///
    /// Only worth driving over the relay: on the LAN the daemon's HTTP API is
    /// right there and says more.
    public let dataChannel = WebRTCDataChannel()

    /// Not `.streaming` for this long after an offer → drop and re-negotiate (upstream value).
    private static let streamTimeout: Duration = .seconds(10)

    private static let factory: RTCPeerConnectionFactory = {
        RTCInitializeSSL()
        return RTCPeerConnectionFactory(
            encoderFactory: RTCDefaultVideoEncoderFactory(),
            decoderFactory: RTCDefaultVideoDecoderFactory()
        )
    }()

    private let signaling: any RobotSignaling
    private let connection: RobotConnection?
    private var peerConnection: RTCPeerConnection?
    private var delegateAdapter: PeerConnectionDelegateAdapter?
    private var micTrack: RTCAudioTrack?
    /// Held so ``micVolume`` can move after the track is attached. The peer owns the
    /// track; nothing else keeps the source alive.
    private var micSource: RTCAudioSource?
    /// `@ObservationIgnored` because `deinit` reads it: the macro would turn a
    /// tracked property into a MainActor-isolated accessor, which a nonisolated
    /// `deinit` may not call — a stored property it may.
    @ObservationIgnored private var eventsTask: Task<Void, Never>?
    private var watchdogTask: Task<Void, Never>?

    private struct LocalCandidate {
        var sdp: String
        var sdpMLineIndex: Int32
        var sdpMid: String?
    }

    /// Local candidates gathered before the answer went out (gst requires answer first).
    private var pendingLocalCandidates: [LocalCandidate] = []
    private var answerSent = false

    /// On the LAN: the robot's own signaling socket, and its HTTP API alongside
    /// for the media-acquire nudge the simulator needs.
    public init(address: RobotAddress) throws {
        signaling = try CameraSignalingClient(address: address)
        connection = try? RobotConnection(address: address)
    }

    /// Anywhere else: whatever is carrying signaling — over the Hugging Face relay
    /// there is no HTTP API to reach, and nothing to acquire.
    public init(signaling: any RobotSignaling) {
        self.signaling = signaling
        connection = nil
    }

    /// The backstop for an owner that drops the session without `stop()`. The
    /// `weak self` in `start()` is what lets this run at all — but on its own it
    /// only half-closes the leak: `eventsTask` keeps consuming, and against an
    /// unreachable robot the captured signaling client redials the socket every
    /// half-second for as long as the app lives, with the `guard let self` never
    /// reached because a dead host yields no events. A stopped (or never
    /// started) session has `eventsTask == nil` and nothing to undo — previews
    /// construct sessions constantly and must not touch the shared audio session.
    ///
    /// `signaling` is bound before the `Task` so the closure never captures
    /// `self`, which a `deinit` may not escape (`RobotFilesModel` sets the idiom).
    deinit {
        guard let eventsTask else { return }
        eventsTask.cancel()
        dataChannel.close()
        let signaling = signaling
        Task { await signaling.disconnect() }
        Task { @MainActor in MediaAudioSession.shared.cameraSessionStopped() }
    }

    public func start() {
        guard eventsTask == nil else { return }
        // Read before anyone can tap, so a mic already refused in Settings shows as
        // refused rather than as an ordinary muted button waiting to be pressed.
        refreshMicPermission()
        MediaAudioSession.shared.cameraSessionStarted()
        // `weak self`: `handle` captures the session, so a strong capture keeps
        // `self → eventsTask → self` alive for as long as the signaling stream
        // runs — an owner that drops the session without `stop()` would leak it
        // and its socket (`RobotSceneModel.startStreaming` makes the same trade).
        eventsTask = Task { [weak self, signaling, connection] in
            // Sim registers no producer until media is acquired; harmless elsewhere.
            try? await connection?.acquireMedia()
            for await event in await signaling.events() {
                guard let self else { return }
                await handle(event)
            }
        }
    }

    public func stop() {
        eventsTask?.cancel()
        eventsTask = nil
        teardownPeer()
        dataChannel.close()
        MediaAudioSession.shared.cameraSessionStopped()
        phase = .connecting
        let signaling = signaling
        Task { await signaling.disconnect() } // best-effort endSession; ws close also suffices
    }

    public func setMicEnabled(_ enabled: Bool) {
        guard enabled else {
            isMicEnabled = false
            micTrack?.isEnabled = false
            return
        }
        Task {
            micPermission = await MicrophonePermission.request()
            guard micPermission == .granted else { return }
            isMicEnabled = true
            micTrack?.isEnabled = true
        }
    }

    /// Re-reads the non-prompting authorization status after the app returns from
    /// Settings. A session survives that round trip, so the value captured by
    /// `start()` would otherwise leave a newly granted microphone looking blocked
    /// until the whole camera session was rebuilt.
    public func refreshMicPermission() {
        micPermission = MicrophonePermission.current
        guard micPermission != .granted else { return }
        isMicEnabled = false
        micTrack?.isEnabled = false
    }

    // MARK: - Signaling events

    private func handle(_ event: SignalingEvent) async {
        switch event {
        case .waitingForProducer:
            if phase != .streaming {
                phase = .waitingForProducer
            }
        case let .offer(_, sdp):
            await accept(offerSDP: sdp)
        case let .remoteCandidate(_, candidate, sdpMLineIndex, sdpMid):
            guard let candidate = Self.iceCandidate(sdp: candidate, sdpMLineIndex: sdpMLineIndex, sdpMid: sdpMid)
            else { return }
            // Late-candidate errors are expected once ICE is connected — ignore (upstream does too).
            try? await peerConnection?.add(candidate)
        case let .sessionEnded(reason):
            teardownPeer()
            // On the LAN the client re-negotiates on its own, so this is a lull
            // rather than an ending. Over the relay central says why, and there is
            // nothing further coming — which is also the line the control channel
            // is drawn on: a lull leaves its commands waiting, an ending fails them.
            guard let reason else {
                phase = .connecting
                return
            }
            dataChannel.close()
            phase = .failed(RemoteSessionEnd(reason: reason).message)
        case let .failed(message):
            teardownPeer()
            dataChannel.close()
            phase = .failed(message)
        }
    }

    private func accept(offerSDP: String) async {
        teardownPeer()
        phase = .connecting

        let configuration = RTCConfiguration()
        configuration.sdpSemantics = .unifiedPlan
        configuration.iceServers = [RTCIceServer(urlStrings: [
            "stun:stun.l.google.com:19302",
            "stun:stun1.l.google.com:19302",
        ])]
        let adapter = PeerConnectionDelegateAdapter(owner: self)
        guard let peer = Self.factory.peerConnection(
            with: configuration, constraints: Self.noConstraints, delegate: adapter
        ) else {
            phase = .failed("Could not create peer connection")
            return
        }
        delegateAdapter = adapter
        peerConnection = peer

        do {
            try await peer.setRemoteDescription(RTCSessionDescription(type: .offer, sdp: offerSDP))
            attachMicTrack(to: peer)
            let answer = try await peer.answer(for: Self.noConstraints)
            try await peer.setLocalDescription(answer)
            await signaling.send(answerSDP: answer.sdp)
            answerSent = true
            for candidate in pendingLocalCandidates {
                await signaling.send(
                    candidate: candidate.sdp,
                    sdpMLineIndex: candidate.sdpMLineIndex,
                    sdpMid: candidate.sdpMid
                )
            }
            pendingLocalCandidates = []
        } catch {
            phase = .failed(error.localizedDescription)
            teardownPeer()
            return
        }
        startWatchdog()
    }

    // MARK: - Peer connection callbacks (from the delegate adapter)

    func handleLocalCandidate(sdp: String, sdpMLineIndex: Int32, sdpMid: String?) {
        guard answerSent else {
            pendingLocalCandidates.append(LocalCandidate(sdp: sdp, sdpMLineIndex: sdpMLineIndex, sdpMid: sdpMid))
            return
        }
        let signaling = signaling
        Task { await signaling.send(candidate: sdp, sdpMLineIndex: sdpMLineIndex, sdpMid: sdpMid) }
    }

    func handleRemote(videoTrack: RTCVideoTrack) {
        self.videoTrack = videoTrack
        phase = .streaming
        watchdogTask?.cancel()
        watchdogTask = nil
    }

    /// ICE failed or the stream never arrived: drop everything and force the
    /// signaling socket closed — its reconnect loop negotiates a fresh session.
    func restartSession() {
        teardownPeer()
        phase = .connecting
        let signaling = signaling
        Task { await signaling.disconnect() }
    }

    // MARK: - Internals

    private func attachMicTrack(to peer: RTCPeerConnection) {
        // ponytail: the mic track is attached even while muted — gst webrtcsink
        // doesn't renegotiate consumer sessions, so audio must be in the answer
        // from the start. Verified: the OS permission prompt still fires only on
        // the first unmute (WebRTC doesn't start capture for a disabled track).
        let source = Self.factory.audioSource(with: Self.noConstraints)
        // Re-applied here rather than only in the setter: a renegotiation builds a new
        // source, and the old one's gain goes with it.
        source.volume = min(max(micVolume, 0), 10)
        let track = Self.factory.audioTrack(with: source, trackId: "reachy-mic")
        track.isEnabled = isMicEnabled
        micSource = source
        if let transceiver = peer.transceivers.first(where: { $0.mediaType == .audio }) {
            transceiver.sender.track = track
            transceiver.setDirection(.sendRecv, error: nil)
        }
        micTrack = track
    }

    private func startWatchdog() {
        watchdogTask?.cancel()
        watchdogTask = Task {
            guard await (try? Task.sleep(for: Self.streamTimeout)) != nil else { return }
            if phase != .streaming {
                restartSession()
            }
        }
    }

    /// The robot opens exactly one channel and labels it `"data"`; anything else
    /// is not the daemon's control surface and is left alone.
    func adopt(_ channel: RTCDataChannel) {
        guard channel.label == "data" else { return }
        dataChannel.attach(channel)
    }

    private func teardownPeer() {
        watchdogTask?.cancel()
        watchdogTask = nil
        dataChannel.detachPeer()
        peerConnection?.close()
        peerConnection = nil
        delegateAdapter = nil
        micTrack = nil
        micSource = nil
        videoTrack = nil
        answerSent = false
        pendingLocalCandidates = []
    }

    private static var noConstraints: RTCMediaConstraints {
        RTCMediaConstraints(mandatoryConstraints: nil, optionalConstraints: nil)
    }
}

#if DEBUG
    public extension CameraSession {
        /// A session parked in one phase. Constructing one is inert — `start()` is what opens the
        /// signaling socket and builds the peer connection, and it is never called here.
        ///
        /// `phase` is `private(set)`, so this has to live in the same file.
        ///
        /// `micPermission` is a parameter because a refused microphone is a state the
        /// viewport renders differently and no preview could otherwise reach: the real
        /// value is only ever written by `start()`, which a preview must not call.
        static func preview(
            _ phase: Phase,
            micPermission: PermissionState = .undetermined,
            isMicEnabled: Bool = false
        ) -> CameraSession {
            // A well-formed host cannot fail to produce a signaling client, and nothing dials it.
            // swiftlint:disable:next force_try
            let session = try! CameraSession(address: RobotAddress(host: "192.168.1.42"))
            session.phase = phase
            session.micPermission = micPermission
            // No track exists without a peer connection, so this is the flag alone —
            // which is all the button and the chrome row read.
            session.isMicEnabled = isMicEnabled
            return session
        }
    }
#endif

import Foundation
import Observation
import ReachyDesign
import ReachyKit
import ReachyMedia
import ReachyScene
import ReachySimulator

/// Owns the two live views of the robot — the 3D model and the camera — and
/// guarantees that only one of them is running.
///
/// The guarantee is the whole point: a viewport that is always on screen would
/// otherwise hold a WebRTC peer connection and a state-stream socket open for as
/// long as the app is in the foreground.
@MainActor
@Observable
final class ViewportModel {
    enum Content: String, CaseIterable, Identifiable {
        case scene
        case camera

        var id: String {
            rawValue
        }

        var title: String {
            switch self {
            case .scene: String(localized: .reachy("3D model"))
            case .camera: String(localized: .reachy("Camera"))
            }
        }

        var systemImage: String {
            switch self {
            case .scene: "cube.transparent"
            case .camera: "video"
            }
        }
    }

    /// Where the live views come from — and, for the camera, who owns them.
    enum Source {
        /// The daemon on this network: a 3D scene built from its URDF, and a
        /// camera session of our own.
        case lan(RobotAddress)
        /// A relay session. The camera is the peer connection that is *already up*
        /// and carrying the robot's commands, so this model borrows it and must
        /// never stop it. There is no HTTP API here, so there is no scene.
        case remote(CameraSession)
        /// A simulator in this very process. It is its own geometry server and its
        /// own state stream, so the scene needs nothing but the object; there is no
        /// camera, because there is nothing to point one at.
        ///
        /// Concrete rather than a pair of existentials: there is exactly one
        /// simulator type, and a class compares by identity the way `.remote` does.
        case simulated(SimulatedRobotClient)
    }

    private(set) var content: Content = .scene
    private(set) var sceneModel: RobotSceneModel?
    private(set) var cameraSession: CameraSession?
    /// Where the robot last heard a voice.
    ///
    /// **Owned here rather than by either engine, because it outlives the switch
    /// between them.** It is the one reading that is worth the same in both views —
    /// over the camera it names somebody the picture cannot show, and over the 3D
    /// model it explains why the head is about to turn. Hanging it off
    /// `RobotSceneModel`, which already receives the frames, would have made it a
    /// property of the 3D tab.
    ///
    /// Nil over the relay: no HTTP API means no state stream, the same reason there
    /// is no scene there.
    private(set) var hearing: DirectionOfArrivalModel?
    /// Set when a transport could not even be constructed — a bad address, not a
    /// failure to reach the robot.
    private(set) var setupError: String?

    private(set) var source: Source?
    /// Whether `cameraSession` is ours to stop. A borrowed one is the same peer
    /// connection the remote control channel rides on: ending it here would take
    /// the robot's commands down with the video, and the viewport scrolling off
    /// screen is not a reason to end a session.
    private var ownsCamera = false
    private var isActive = false

    /// How loud this device's voice comes out of the robot, where 1 is unchanged.
    ///
    /// **The one control over the loudness a person actually complains about.** The
    /// daemon applies no software gain and its mixer is already at 100, so the robot
    /// cannot play a sound louder to match a call — the call has to come down to meet
    /// the sounds. Stored on the device rather than on the robot, because it scales
    /// *this* microphone.
    var callMicVolume: Double = UserDefaults.standard.object(forKey: ViewportModel.micVolumeKey) as? Double ?? 1 {
        didSet {
            UserDefaults.standard.set(callMicVolume, forKey: ViewportModel.micVolumeKey)
            cameraSession?.micVolume = callMicVolume
        }
    }

    static let micVolumeKey = "callMicVolume"
    /// Below 0.1 a voice is gone rather than quiet, and above 2 the encoder clips
    /// before the robot gets louder. libwebrtc itself accepts 0…10.
    static let micVolumeRange: ClosedRange<Double> = 0.1 ... 2

    var address: RobotAddress? {
        if case let .lan(address) = source {
            address
        } else {
            nil
        }
    }

    /// Which sources have a 3D model at all: the switcher is not what decides
    /// whether to offer one — the source is. Only the relay has none.
    var offersScene: Bool {
        switch source {
        case .lan, .simulated: true
        case .remote, nil: false
        }
    }

    /// Whether the joystick belongs over the 3D model as well as over the camera.
    ///
    /// Only the simulator, and the reason is what the model *is* there: the
    /// simulator is its own robot, so the scene is the thing being driven rather
    /// than a picture of it. A LAN robot's scene mirrors the state stream, and a
    /// pad over it would move a model while the camera — the view a person checks
    /// the robot against — sits behind another segment. That one keeps its
    /// joystick over the video, where the two agree.
    var offersSceneTeleop: Bool {
        switch source {
        case .simulated: true
        case .lan, .remote, nil: false
        }
    }

    /// Why there is no 3D model, where there is a reason rather than a wait.
    var sceneUnavailableReason: String? {
        guard case .remote = source else { return nil }
        return String(
            localized: .reachy(
                "The robot's 3D description is served over its own network, which a relay session cannot reach."
            )
        )
    }

    /// Re-attaching to the same source is a no-op, so a SwiftUI redraw cannot
    /// restart the download. A different one tears everything down first — one
    /// robot can appear at several addresses, but the geometry is per robot.
    func attach(to source: Source) {
        guard self.source != source else { return }
        detach()
        self.source = source
        // Each source has one content it can actually show first: the relay has
        // only video, and a simulator has only the model. Landing on the other
        // would be an empty pane in both directions.
        switch source {
        case .remote: content = .camera
        case .simulated: content = .scene
        case .lan: break
        }
        activate()
    }

    func detach() {
        sceneModel?.stop()
        sceneModel = nil
        stopCamera()
        // Dropped rather than merely stopped: `detach` is a different robot, and a
        // held reading would be the previous one's.
        stopHearing()
        hearing = nil
        source = nil
        setupError = nil
    }

    func setContent(_ next: Content) {
        guard content != next else { return }
        guard next != .scene || offersScene else { return }
        content = next
        activate()
    }

    /// The single lever for "is the viewport on screen": the Live tab's appearance
    /// on compact, the scene phase everywhere.
    func setActive(_ active: Bool) {
        guard isActive != active else { return }
        isActive = active
        if active {
            activate()
        } else {
            suspend()
        }
    }

    /// Starts whichever engine `content` names and shuts the other one down.
    private func activate() {
        guard isActive, let source else { return }
        setupError = nil
        // Outside the switch on purpose: it is wanted under both contents, and the
        // one thing that decides it is whether this connection has a state stream
        // at all.
        if case let .lan(address) = source {
            startHearing(at: address)
        }
        switch (content, source) {
        case let (.scene, .lan(address)):
            stopCamera()
            startScene(at: address)
        case (.scene, .remote):
            // Nothing to start. `sceneUnavailableReason` is what the view renders,
            // rather than a spinner that would never resolve.
            break
        case let (.camera, .lan(address)):
            // Paused rather than stopped: the meshes stay in memory, so coming
            // back to 3D does not re-download the robot's description.
            sceneModel?.pauseStream()
            startCamera(at: address)
        case let (.scene, .simulated(client)):
            stopCamera()
            startSimulatedScene(client)
        case (.camera, .simulated):
            // Unreachable in practice and stated rather than assumed: a simulator
            // reports no `camera_specs_name`, so `session.hasCamera` is false and
            // `ViewportOptions.offered` never puts `.camera` in the switcher. The
            // arm exists because a source change must not be able to land here
            // silently.
            break
        case let (.camera, .remote(session)):
            // Already running — `RemoteRobotLink` started it, and it is the same
            // connection the commands are on. Adopted, never started or stopped.
            cameraSession = session
            // Adopted, so nothing here built the track — the gain still has to reach it.
            session.micVolume = callMicVolume
            ownsCamera = false
        }
    }

    private func suspend() {
        sceneModel?.pauseStream()
        stopCamera()
        stopHearing()
    }

    /// Idempotent, and it keeps the model across a suspend so a reading still inside
    /// its window survives a glance at another tab. Only `detach()` throws it away,
    /// because that is a different robot.
    private func startHearing(at address: RobotAddress) {
        if hearing == nil {
            // An address no socket can be built from leaves an inert model rather
            // than an error: this indicator has never had a failure state, and one
            // reading fewer is not worth a banner over the viewport.
            hearing = DirectionOfArrivalModel(stream: try? RobotStateStream(address: address))
        }
        hearing?.start()
    }

    private func stopHearing() {
        hearing?.stop()
    }

    private func startSimulatedScene(_ client: SimulatedRobotClient) {
        if sceneModel == nil {
            // One object for both roles: it serves the geometry out of the app's
            // bundle and publishes the state stream itself, which is the whole
            // reason the `RobotStateStreaming` seam exists.
            sceneModel = RobotSceneModel(stream: client, client: client)
        }
        sceneModel?.start()
        sceneModel?.resumeStream()
    }

    private func startScene(at address: RobotAddress) {
        if sceneModel == nil {
            guard let connection = try? RobotConnection(address: address),
                  let stream = try? RobotStateStream(address: address)
            else {
                setupError = String(localized: .reachy("Could not reach \(address.host)"))
                return
            }
            sceneModel = RobotSceneModel(stream: stream, client: connection)
        }
        // Both are idempotent; whichever applies at this point is the one that runs.
        sceneModel?.start()
        sceneModel?.resumeStream()
    }

    private func startCamera(at address: RobotAddress) {
        guard cameraSession == nil else { return }
        guard let session = try? CameraSession(address: address) else {
            setupError = String(localized: .reachy("Could not reach \(address.host)"))
            return
        }
        cameraSession = session
        ownsCamera = true
        session.micVolume = callMicVolume
        session.start()
    }

    /// WebRTC has no cheap pause — a session we built is dropped and renegotiated
    /// from scratch next time. A borrowed one is only let go of: over the relay it
    /// is the connection the robot is being controlled through, so stopping it to
    /// save battery would disconnect the robot.
    private func stopCamera() {
        if ownsCamera {
            cameraSession?.stop()
        }
        cameraSession = nil
        ownsCamera = false
    }
}

extension ViewportModel.Source: Equatable {
    /// Two borrowed cameras are the same source only when they are the same
    /// object — `CameraSession` is a reference type with no value identity, and
    /// `.task(id:)` in the root view compares these to decide whether to re-attach.
    static func == (lhs: Self, rhs: Self) -> Bool {
        switch (lhs, rhs) {
        case let (.lan(lhs), .lan(rhs)): lhs == rhs
        case let (.remote(lhs), .remote(rhs)): lhs === rhs
        case let (.simulated(lhs), .simulated(rhs)): lhs === rhs
        default: false
        }
    }
}

#if DEBUG
    extension ViewportModel {
        /// Assembled rather than attached: `attach(to:)` would build a real `RobotConnection` and
        /// a real `CameraSession`. Lives here because every field below is `private(set)`.
        static func preview(
            content: Content = .scene,
            sceneModel: RobotSceneModel? = nil,
            cameraSession: CameraSession? = nil,
            setupError: String? = nil,
            address: RobotAddress? = RobotAddress(host: "192.168.1.42"),
            // Overrides `address` where the transport is the point. Defaulted from
            // it so every preview written before the relay existed is unchanged.
            source: Source? = nil,
            // Nil by default, so the direction-of-arrival badge is absent from every
            // reference that predates it and none of them moved when it landed. A
            // preview that wants the badge injects a settled model, which is built
            // with no stream and therefore has no socket to open.
            hearing: DirectionOfArrivalModel? = nil,
            // Always assigned, never left to the stored default: the real one reads
            // `UserDefaults`, so a preview that took whatever a previous one wrote
            // would render a different slider on each run.
            callMicVolume: Double = 1
        ) -> ViewportModel {
            let model = ViewportModel()
            model.callMicVolume = callMicVolume
            model.content = content
            model.sceneModel = sceneModel
            model.cameraSession = cameraSession
            model.setupError = setupError
            model.source = source ?? address.map(Source.lan)
            model.hearing = hearing
            return model
        }
    }
#endif

